// Compact currency units are keyed, not literal copy: ID "jt"/"M" (juta/miliar),
// EN "M"/"B". Keyed explicitly because "M" means billion in ID but million in EN.
insights['million short'] = ['jt', 'M'];
insights['billion short'] = ['M', 'B'];

